import { ChangeDetectionStrategy, Component, OnInit } from '@angular/core';
import {
  CreateFinishedProductInwardDto,
  CreateFinishedProductInwardRequest,
  FinishedProductInward,
  FinishedProductInwardService,
  SFOutwardDto,
} from '../../services/finished-product-inward-service';
import {
  FormGroup,
  FormBuilder,
  Validators,
  ReactiveFormsModule,
  FormsModule,
  FormControl,
} from '@angular/forms';
import { ProductService } from '../../services/product-service';
import { SemiFinishedService } from '../../services/semi-finished-service';
import { Product, SemiFinished } from '../../models/invoice';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';

@Component({
  selector: 'app-add-finished-product-inward',
  templateUrl: './add-finished-product-inward.html',
  styleUrls: ['./add-finished-product-inward.css'],
  imports: [ReactiveFormsModule, CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AddFinishedProductInward implements OnInit {
  inwardForm!: FormGroup;
  semiFinishedForm!: FormGroup;

  products: Product[] = [];
  semiFinishedProducts: SemiFinished[] = [];
  dataList: SFOutwardDto[] = [];
  bagStock = 0;
  grossQtyStock = 0;

  constructor(
    private fb: FormBuilder,
    private inwardService: FinishedProductInwardService,
    private productService: ProductService,
    private semiFinishedService: SemiFinishedService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.inwardForm = this.fb.group({
      productId: [0, Validators.required],
      lotNo: ['', Validators.required],
      bags: [0, [Validators.required, Validators.min(1)]],
      kgBags: [0, [Validators.required, Validators.min(1)]],
       grossQty: [0, Validators.required],
      inwardDate: [
        new Date().toISOString().substring(0, 10),
        Validators.required,
      ],
    });

    this.semiFinishedForm = this.fb.group({
      semiFinishedId: [0, Validators.required],
      bags: [0, [Validators.required, Validators.min(1)]],
      kgBags: [0, [Validators.required, Validators.min(1)]],
      grossQty: [0, Validators.required],
    });

    this.loadProducts();
    this.loadSemiFinishedProducts();

    this.inwardForm.valueChanges.subscribe(() => this.calculateGrossQty());
    this.semiFinishedForm.valueChanges.subscribe(() =>
      this.calculateSFGrossQty()
    );
  }

  // --- Load Data ---
  loadProducts() {
    this.productService.getAllProducts().subscribe({
      next: (data) => (this.products = data),
      error: (err) => console.error('Failed to load finished products', err),
    });
  }

  loadSemiFinishedProducts() {
    this.semiFinishedService.getAllProducts().subscribe({
      next: (data) => (this.semiFinishedProducts = data),
      error: (err) =>
        console.error('Failed to load semi-finished products', err),
    });
  }

  // --- Compute Gross Quantity ---
  calculateGrossQty() {
    const bags = this.inwardForm.value.bags || 0;
    const kg = this.inwardForm.value.kgBags || 0;
    this.inwardForm.patchValue({ grossQty: bags * kg }, { emitEvent: false });
  }

  calculateSFGrossQty() {
    const bags = this.semiFinishedForm.value.bags || 0;
    const kg = this.semiFinishedForm.value.kgBags || 0;
    this.semiFinishedForm.patchValue(
      { grossQty: bags * kg },
      { emitEvent: false }
    );
  }

  // --- Semi-Finished Logic ---
onSemiFinishedChange() {
  const id = Number(this.semiFinishedForm.value.semiFinishedId);
  if (!id) return;

  // prevent duplicate
  const exists = this.dataList.find(d => d.semiFinishedId === id);
  if (exists) {
    alert('Product already added to list!');
    this.semiFinishedForm.patchValue({ semiFinishedId: 0 });
    return;
  }

  // find in cached list
  const selected = this.semiFinishedProducts.find(sf => sf.id === id);
  if (selected) {
    this.bagStock = selected.bagStock || 0;
    this.grossQtyStock = selected.grossQtyStock || 0;
  }
}


  addSFToList() {
    const sf = this.semiFinishedForm.value;
    if (sf.bags <= 0 || sf.kgBags <= 0 || sf.grossQty <= 0) {
      alert('Enter valid quantity');
      return;
    }
    if (sf.grossQty > (this.grossQtyStock || 0)) {
      alert('Insufficient stock');
      return;
    }

    const sfId = Number(sf.semiFinishedId); // <-- convert to number
  const name = this.semiFinishedProducts.find(p => p.id === sfId)?.name || '';
      const semi = this.semiFinishedForm.value;
         console.log(semi); // <-- Add this

      console.log(this.semiFinishedProducts);

    const grossQty = sf.bags * sf.kgBags;
    const newItem: SFOutwardDto = {
      semiFinishedId: sfId,
      semiFinishedName: name,
      bags: sf.bags,
      kgBags: sf.kgBags,
      grossQty: grossQty,
    };
    this.dataList = [...this.dataList, newItem];

    this.semiFinishedForm.reset({
      semiFinishedId: 0,
      bags: 0,
      kgBags: 0,
      grossQty: 0,
    });
    this.bagStock = 0;
    this.grossQtyStock = 0;
  }

  removeSFFromList(index: number) {
    this.dataList = this.dataList.filter((_, i) => i !== index);
  }
  get sfId(): FormControl {
    return this.semiFinishedForm.get('semiFinishedId') as FormControl;
  }

  get sfBags(): FormControl {
    return this.semiFinishedForm.get('bags') as FormControl;
  }

  get sfKgBags(): FormControl {
    return this.semiFinishedForm.get('kgBags') as FormControl;
  }

  get sfGrossQty(): FormControl {
    return this.semiFinishedForm.get('grossQty') as FormControl;
  }
  // --- Save to Backend ---
  saveInward() {
    if (this.inwardForm.invalid) {
      alert('Please fill all required fields!');
      return;
    }
    if (this.dataList.length === 0) {
      alert('Add at least one semi-finished product!');
      return;
    }
const selectedProduct = this.products.find(
  (p) => p.id === +this.inwardForm.value.productId
);
const request = {
  productId: +this.inwardForm.value.productId, // number
  productName: selectedProduct?.productName || '', // optional if API requires
  lotNo: this.inwardForm.value.lotNo,
  bags: this.inwardForm.value.bags,
  perKg: this.inwardForm.value.kgBags,
  grossQty: this.inwardForm.value.grossQty,
  semiFinishedId: this.dataList[0]?.semiFinishedId || 0, // pick the first SF
  inwardDate: this.inwardForm.value.inwardDate
};
    // inside AddFinishedProductInward class
    console.log("submitting Inward", request)
    this.inwardService.addInward(request).subscribe({
      next: () => {
        alert('Finished product inward saved successfully!');
        this.inwardForm.reset({
          lotNo: '',
          productId: null,
          bags: 0,
          kgBags: 0,
          grossQty: 0,
          inwardDate: new Date().toISOString().substring(0, 10),
        });
        this.dataList = [];
        this.router.navigate(['/finished-product-inward'])
      },
      error: (err) => alert('Failed to save: ' + err),
    });
  }
}
